/* Generated by Brickwright — blocks → C for the STC12 / 8051.
 * Regenerating from the project overwrites this file. Your edits are not
 * stuck here though — the C reader imports this back into blocks, and it
 * names anything it cannot represent rather than dropping it in silence.
 */
/* @bw-begin — machine-readable; do not hand-edit.
 * @bw device arduino-uno
 * @bw clock 16000000
 * @bw pin sensor A0 analog
 * @bw var s0_total "total" sprite "Cat"
 * @bw var s0_numReadings "numReadings" sprite "Cat"
 * @bw var s0_readIndex "readIndex" sprite "Cat"
 * @bw var s0_average "average" sprite "Cat"
 * @bw list bw_list_s0_readings_data "readings" sprite "Cat"
 * @bw script bw_task0 0 sprite "Cat"
 * @bw yield bw_task0 0 - hat
 * @bw yield bw_task0 1 - repeat
 * @bw yield bw_task0 2 - forever
 * @bw yield bw_task0 3 - wait
 * @bw-end */
#include <avr/io.h>
#include <avr/interrupt.h>
#include <avr/sleep.h>
#include <stdint.h>

#define F_CPU 16000000UL

/* Timer 0 in CTC mode ticks every millisecond: F_CPU/64 counts,
 * OCR0A picked so one compare = 1 ms exactly at this clock. The same
 * one-tick contract the 8051 build keeps — nothing generated here
 * ever busy-waits on a cycle count. */
#define BW_OCR0A ((uint8_t)(F_CPU / 64UL / 1000UL - 1UL))

/* One script = one cooperative task. Timer interrupts every millisecond;
 * tasks yield at every wait and at every loop iteration (Scratch's own
 * scheduling contract), so no task can starve the others. */
static volatile uint32_t bw_ms;
static uint8_t bw_calm;

ISR(TIMER0_COMPA_vect)
{
    bw_ms++;
}

/* A 32-bit read is not atomic on an 8-bit AVR; hold interrupts off. */
static uint32_t bw_now(void)
{
    uint32_t t;
    cli();
    t = bw_ms;
    sei();
    return t;
}

/* print goes out UART0 at 9600 8N1 — the same wire the 8051 build uses,
 * so the serial monitor does not care which chip is talking. */
static void bw_putc(char c)
{
    while (!(UCSR0A & (1 << UDRE0))) ;
    UDR0 = (uint8_t)c;
}

static void bw_print(const char *s)
{
    while (*s) bw_putc(*s++);
    bw_putc(13); bw_putc(10);
}

static void bw_print_num(long n)
{
    char buf[12]; unsigned char i = 0;
    unsigned long u;
    if (n < 0) { bw_putc(45); u = (unsigned long)(-n); } else { u = (unsigned long)n; }
    do { buf[i++] = (char)(48 + (u % 10)); u /= 10; } while (u);
    while (i) bw_putc(buf[--i]);
    bw_putc(13); bw_putc(10);
}

/* 10-bit ADC, polled, AVcc reference. Channel = the A-pin number;
 * A6/A7 exist on the Nano as ADC-only pads and work here too. */
static long adc_read(unsigned char channel)
{
    ADMUX = (uint8_t)((1 << REFS0) | (channel & 0x0F));
    ADCSRA |= (1 << ADSC);
    while (ADCSRA & (1 << ADSC)) ;
    return ADC;
}

/* Lists: 32 numbers each (Scratch lists, numeric only). A one-based
 * index out of range is a no-op, or 0 when read, as Scratch coerces it;
 * adding to a full list is refused (the item is dropped and a flag set). */
#define BW_LIST_CAPACITY 32u
static unsigned char bw_list_full;
static long bw_list_item(long *data, unsigned len, long index)
{
    if (index < 1 || (unsigned long)index > len) return 0;
    return data[(unsigned)index - 1u];
}
static void bw_list_add(long *data, unsigned *len, long value)
{
    if (*len >= BW_LIST_CAPACITY) { bw_list_full = 1; return; }
    data[*len] = value; *len = *len + 1u;
}
static void bw_list_delete(long *data, unsigned *len, long index)
{
    unsigned i;
    if (index < 1 || (unsigned long)index > *len) return;
    for (i = (unsigned)index; i < *len; ++i) data[i - 1u] = data[i];
    *len = *len - 1u;
}
static void bw_list_insert(long *data, unsigned *len, long index, long value)
{
    unsigned i;
    if (index < 1 || (unsigned long)index > *len + 1u) return;
    if (*len >= BW_LIST_CAPACITY) { bw_list_full = 1; return; }
    i = *len; while (i >= (unsigned)index) { data[i] = data[i - 1u]; --i; }
    data[(unsigned)index - 1u] = value; *len = *len + 1u;
}
static void bw_list_replace(long *data, unsigned len, long index, long value)
{
    if (index < 1 || (unsigned long)index > len) return;
    data[(unsigned)index - 1u] = value;
}

/* Variables: long, matching Scratch's number range — int is 16-bit on
 * sdcc/avr-gcc/cc65 and silently wraps mid-expression (76-multimeter). */
static long s0_total = 0;   /* Cat: total */
static long s0_numReadings = 0;   /* Cat: numReadings */
static long s0_readIndex = 0;   /* Cat: readIndex */
static long s0_average = 0;   /* Cat: average */
static long bw_list_s0_readings_data[32] = { 0 };
static unsigned bw_list_s0_readings_len = 0u;

/* REPEAT counters live across yields. */
static long bw_i1;

/* forward declarations — print helpers defined after the timer section */
static void bw_putc(char c);
static void bw_print(const char *s);
static void bw_print_num(long n);

static volatile unsigned int bw_task0_state;
static volatile unsigned int bw_task0_until;
// Ported from arduino-examples/examples/03.Analog/Smoothing/Smoothing.ino, CC0
/* when green flag clicked (script 1, Cat) */
static void bw_task0(void)
{
    switch (bw_task0_state) {
    case 0:
    s0_total = 0;
    s0_numReadings = 10;
    s0_readIndex = 0;
    /* Initialize readings list */
    bw_list_s0_readings_len = 0;
    bw_i1 = (s0_numReadings);
    bw_task0_state = 1;
    case 1:
    if (bw_i1 > 0) {
        bw_list_add(bw_list_s0_readings_data, &bw_list_s0_readings_len, 0);
        bw_i1--;
        bw_task0_state = 1;
        return;
    }
    bw_task0_state = 2;
    case 2:
    s0_total = (s0_total - bw_list_item(bw_list_s0_readings_data, bw_list_s0_readings_len, (s0_readIndex + 1)));
    bw_list_replace(bw_list_s0_readings_data, bw_list_s0_readings_len, (s0_readIndex + 1), adc_read(0));
    s0_total = (s0_total + bw_list_item(bw_list_s0_readings_data, bw_list_s0_readings_len, (s0_readIndex + 1)));
    s0_readIndex += 1;
    if ((!(s0_readIndex < s0_numReadings))) {
        s0_readIndex = 0;
    }
    s0_average = (s0_total / s0_numReadings);
    bw_print_num(s0_average);
    bw_task0_until = bw_now() + (10);
    bw_task0_state = 3;
    case 3:
    if ((int)(bw_now() - bw_task0_until) < 0) return;
    bw_task0_state = 2;
    return;
    }
    bw_task0_state = 0xFFFF;   /* ran to the end */
}

/* Register setup: ports, ADC, Timer 0. Kept out of main() so the program
 * body stands alone — a C -> blocks reader can then tell them apart. */
static void bw_setup(void)
{
    DIDR0 |= (1 << 0);     /* sensor: digital buffer off on ADC0 */
    ADCSRA = (1 << ADEN) | (1 << ADPS2) | (1 << ADPS1) | (1 << ADPS0);  /* on, /128 */
    TCCR0A = (1 << WGM01);         /* Timer 0 CTC */
    TCCR0B = (1 << CS01) | (1 << CS00);  /* F_CPU/64 */
    OCR0A  = BW_OCR0A;             /* one compare = 1 ms */
    TIMSK0 = (1 << OCIE0A);        /* millisecond tick */
    UBRR0 = (uint16_t)(F_CPU / 16UL / 9600UL - 1UL);
    UCSR0B = (1 << TXEN0);         /* transmit only */
    UCSR0C = (1 << UCSZ01) | (1 << UCSZ00);  /* 8N1 */
}

int main(void)
{
    bw_setup();
    set_sleep_mode(SLEEP_MODE_IDLE);  /* timers keep running; the tick wakes us */
    sleep_enable();
    sei();                         /* tick on */

    for (;;) {
        uint32_t pass_ms = bw_now();
        bw_task0();
        /* Two full passes inside one millisecond: sleep to the next
         * tick instead of spinning the core against it — the same
         * contract the pico target keeps (its DONE row has the 110x
         * measurement), spelled in avr-libc. The emulator adapter
         * fast-forwards the SLEEP opcode; silicon idles. */
        if (bw_now() == pass_ms) { if (++bw_calm >= 2u) { bw_calm = 0u; sleep_cpu(); } }
        else bw_calm = 0u;
    }
}
